input.content:
"use strict";
/* =========================================================
   IRON HAUL v2 — mobile top-down train survival (single file)
   World: +x east, +y south. Train drives NORTH (y decreases).
   10 px = 1 meter. Goal: reach 3000 m.
   v2: cart building, on-deck walking, per-cart functions.
   ========================================================= */
const cv = document.getElementById('cv'), ctx = cv.getContext('2d');
let W = 0, H = 0, DPR = 1;
function resize(){
  DPR = Math.min(window.devicePixelRatio || 1, 2);
  W = window.innerWidth; H = window.innerHeight;
  cv.width = W * DPR; cv.height = H * DPR;
  cv.style.width = W + 'px'; cv.style.height = H + 'px';
}
window.addEventListener('resize', resize); resize();

/* ---------- constants ---------- */
const PPM = 10, GOAL_M = 3000;
const TRAIN_SPD = 105, FUEL_DRAIN = 1.5, PLAYER_SPD = 170;
const CHUNK = 420;
const LOCO_LEN = 150, CART_LEN = 62, COUP = 10, TENDER0 = 160;

/* ---------- cart catalogue ---------- */
const CART_DEFS = {
  workshop: { name:'WORKSHOP',   icon:'🔧', cost:{ wood:6, scrap:4 },            desc:'Mobile workshop. Stand inside to build more cars.' },
  plow:     { name:'COW PLOW',   icon:'🔱', cost:{ wood:8, scrap:6 },            desc:'Front wedge — smashes debris on the rails.' },
  bunker:   { name:'COAL BUNKER',icon:'⚫', cost:{ wood:5, coal:2, scrap:4 },    desc:'+40 max fuel capacity.' },
  green:    { name:'GREENHOUSE', icon:'🌱', cost:{ wood:8, scrap:2, food:1 },    desc:'Grows food while the train is rolling.' },
  turret:   { name:'TURRET',     icon:'🔫', cost:{ wood:4, coal:2, scrap:8 },    desc:'Auto-fires at infected near the train.' },
  medic:    { name:'INFIRMARY',  icon:'⛑️', cost:{ wood:6, scrap:4, food:2 },    desc:'Heals you while you stand on it.' },
};

/* ---------- state ---------- */
const S = {
  mode: 'title', t: 0,
  train: { y: 0, moving: true, fuel: 55, carts: [] },
  inv: { wood: 2, coal: 2, scrap: 2, food: 1 },
  player: { x: 0, y: 120, lx: 0, ly: 120, aboard: true, hp: 100,
            dir: -Math.PI/2, atkT: 0, hurtT: 0 },
  cam: { x: 0, y: 0 },
  zombies: [], parts: [], texts: [], smoke: [], beams: [],
  joy: { active: false, id: -1, bx: 0, by: 0, dx: 0, dy: 0 },
  keys: {},
  hitFlash: 0, shake: 0, toastT: 0,
};
const dist_m = () => Math.max(0, -S.train.y / PPM);

/* ---------- train geometry ---------- */
function trainLen(){ return TENDER0 + CART_LEN + (CART_LEN + COUP) * S.train.carts.length; }
function segs(){
  const out = [{ type:'loco', y0:0, y1:LOCO_LEN }];
  out.push({ type:'tender', y0:TENDER0, y1:TENDER0 + CART_LEN });
  let off = TENDER0 + CART_LEN + COUP;
  for (const c of S.train.carts){ out.push({ type:c.type, y0:off, y1:off+CART_LEN, ref:c }); off += CART_LEN + COUP; }
  return out;
}
function nCarts(type){ return S.train.carts.filter(c => c.type === type).length; }
const hasPlow = () => nCarts('plow') > 0;
function fuelMax(){ return 100 + 40 * nCarts('bunker'); }
function zoneAt(ly){
  const t = S.train;
  if (ly >= 0 && ly < LOCO_LEN) return { type:'loco', y0:0, y1:LOCO_LEN };
  if (ly >= TENDER0 && ly < TENDER0 + CART_LEN) return { type:'tender', y0:TENDER0, y1:TENDER0+CART_LEN };
  let off = TENDER0 + CART_LEN + COUP;
  for (const c of t.carts){
    if (ly >= off && ly < off + CART_LEN) return { type:c.type, y0:off, y1:off+CART_LEN, ref:c };
    off += CART_LEN + COUP;
  }
  return null;
}
const inCab = () => S.player.aboard && S.player.ly >= 96 && S.player.ly < LOCO_LEN;
function inZone(type){
  if (!S.player.aboard) return false;
  const z = zoneAt(S.player.ly);
  return !!(z && z.type === type);
}

/* ---------- utils ---------- */
const clamp = (v,a,b)=>v<a?a:v>b?b:v;
const lerp = (a,b,k)=>a+(b-a)*k;
function mul32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);
  t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
function toast(msg){ const el=document.getElementById('toast'); el.textContent=msg;
  el.style.opacity=1; S.toastT=1.6; }
function puff(x,y,c,n=6,spd=60){ for(let i=0;i<n;i++){const a=Math.random()*6.28,s=spd*(.4+Math.random()*.8);
  S.parts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,t:.5+Math.random()*.4,c:typeof c==='string'?c:c()}); } }
function addText(x,y,txt,c){ S.texts.push({x,y,txt,c,t:1}); }

/* ---------- world generation ---------- */
const chunks = new Map();
function genChunk(ci){
  const r = mul32(9176 + ci * 7919);
  const list = [];
  const y0 = ci * CHUNK, y1 = y0 + CHUNK;
  for (let i = 0; i < 5; i++)
    list.push({ type:'patch', x:(r()*2-1)*520, y:y0+r()*CHUNK, s:26+r()*46, tone:r() });
  const depth = clamp(Math.abs(y0) / (GOAL_M*PPM), 0, 1);
  const station = ci % 4 === 0;
  if (station){
    const side = (ci/4|0) % 2 === 0 ? -1 : 1;
    const bx = side * 185, by = y0 + 40 + r()*(CHUNK-140);
    list.push({ type:'depot', x:bx, y:by });
    for (let i = 0; i < 3; i++){
      const a = r()*6.28, d = 85 + r()*70;
      const kinds = ['scrap','food','coal','wood'];
      list.push({ type:kinds[(r()*kinds.length)|0], x:bx+Math.cos(a)*d, y:by+Math.sin(a)*d,
        amt: 1 + (r()*2|0) });
    }
    list.push({ type:'zs', x:bx+side*60, y:by+90, n: 2 + Math.round(depth*3) + (r()*2|0) });
  }
  const nRes = 4 + (r()*4|0);
  for (let i = 0; i < nRes; i++){
    const roll = r();
    let type = 'grass';
    if (roll < .30) type = 'tree';
    else if (roll < .44) type = 'coal';
    else if (roll < .58) type = 'wood';
    else if (roll < .72) type = 'scrap';
    else if (roll < .80) type = 'food';
    else if (roll < .88) type = 'rock';
    let x = (r()*2-1)*480;
    if (Math.abs(x) < 75) x += x < 0 ? -80 : 80;
    list.push({ type, x, y: y0 + r()*CHUNK, amt: 1 + (r()*3|0), s: r() });
  }
  for (let i = 0; i < 8; i++){
    let x = (r()*2-1)*500; if (Math.abs(x) < 60) x += 70*(x<0?-1:1);
    list.push({ type:'grass', x, y:y0+r()*CHUNK, s:r() });
  }
  // track debris (logs / rock piles on the rails)
  if (r() < .24 && ci < 0){
    list.push({ type:'debris', kind: r()<.5?'log':'rocks', x:0, y:y0 + 30 + r()*(CHUNK-60),
      hp:2, amt: 1 + (r()*2|0) });
  }
  for (let m = Math.max(1, Math.ceil(-y1/(100*PPM))); m*100*PPM <= -y0 && m <= GOAL_M/100; m++){
    list.push({ type:'sign', x: (m%2? -1:1)*64, y: -m*100*PPM, m: m*100 });
  }
  if (y0 <= -GOAL_M*PPM && y1 >= -GOAL_M*PPM) list.push({ type:'finish', x:0, y:-GOAL_M*PPM });
  chunks.set(ci, list);
  for (const p of list) if (p.type === 'zs') spawnZs(p);
  return list;
}
function propsInView(cy, pad){
  const a = Math.floor((cy - H*0.62 - pad) / CHUNK), b = Math.floor((cy + H*0.62 + pad) / CHUNK);
  const out = [];
  for (let ci = a; ci <= b; ci++){ const c = chunks.get(ci) || genChunk(ci); out.push(...c); }
  return out;
}

/* ---------- zombies ---------- */
function spawnZs(zp){
  for (let i = 0; i < zp.n; i++){
    if (S.zombies.length > 42) break;
    S.zombies.push({ x: zp.x + (Math.random()*2-1)*70, y: zp.y + (Math.random()*2-1)*70,
      hx: zp.x, hy: zp.y, hp: 3, wob: Math.random()*6.28, t: Math.random()*10 });
  }
}
function killZombie(i, x, y, reward){
  S.zombies.splice(i,1); puff(x,y,'#4a6a3a',10,85);
  if (reward === 'scrap'){ S.inv.scrap++; addText(x,y,'+1 SCRAP','#9fd39f'); }
}
function zUpdate(dt){
  const p = S.player, spd = 62 + Math.min(45, dist_m()/45);
  for (let i = S.zombies.length-1; i >= 0; i--){
    const z = S.zombies[i]; z.t += dt;
    const dpx = p.x - z.x, dpy = p.y - z.y, dp = Math.hypot(dpx,dpy);
    if (!p.aboard && dp < 360){
      z.x += dpx/dp * spd * dt; z.y += dpy/dp * spd * dt;
      if (dp < 25 && p.hurtT <= 0){ damage(8); p.hurtT = .55; puff(p.x,p.y,'#a33',4,40); }
    } else {
      const a = Math.sin(z.t*.7 + z.wob)*2.4, hx = z.hx + Math.cos(a)*46, hy = z.hy + Math.sin(a)*46;
      const dx = hx-z.x, dy = hy-z.y, d = Math.hypot(dx,dy)||1;
      z.x += dx/d * 18 * dt; z.y += dy/d * 18 * dt;
    }
    if (S.train.moving && S.train.fuel > 0 && Math.abs(z.x) < 26 &&
        z.y > S.train.y - 30 && z.y < S.train.y + trainLen() + 8)
      killZombie(i, z.x, z.y, 'scrap');
    else if (Math.abs(z.y - S.cam.y) > 1900) S.zombies.splice(i,1);
  }
}

/* ---------- interactions ---------- */
function damage(n){ S.player.hp -= n; S.hitFlash = 1;
  if (S.player.hp <= 0){ S.player.hp = 0; S.mode = 'dead'; showOverlay('dead'); } }
function nearestRes(){
  let best=null,bd=30;
  for (const p of propsInView(S.player.y, 200)){
    if (!p.amt || p.amt<=0 || p.taken) continue;
    const d = Math.hypot(p.x-S.player.x, p.y-S.player.y);
    if (d < bd){ bd=d; best=p; }
  }
  return best;
}
function collect(p){
  p.taken = true;
  const names = {coal:'COAL',wood:'WOOD',scrap:'SCRAP',food:'CANNED FOOD'};
  if (names[p.type]){ S.inv[p.type] += p.amt; addText(p.x,p.y-14,'+'+p.amt+' '+names[p.type],'#ffe9b0');
    puff(p.x,p.y,'#e8d27a',7,55); }
  else if (p.type==='tree'){ S.inv.wood += p.amt+1; addText(p.x,p.y-14,'+'+(p.amt+1)+' WOOD','#b8e0a0');
    puff(p.x,p.y,'#5a8f4a',9,70); }
}
function trainNear(maxD){
  const p = S.player, t = S.train; let best = null, bd = maxD;
  for (const s of segs()){
    const py = clamp(p.y, t.y + s.y0, t.y + s.y1);
    const d = Math.hypot(p.x - clamp(p.x,-23,23), p.y - py);
    if (d <= bd){ bd = d; best = py; }
  }
  return best;
}
const trainStopped = () => !S.train.moving;
function canBoard(){ return !S.player.aboard && trainStopped() && trainNear(60) !== null; }
function fallOff(){
  const p = S.player, t = S.train;
  p.aboard = false;
  const side = p.lx < 0 ? -1 : 1;
  p.x = side * 32; p.y = t.y + clamp(p.ly, -8, trainLen() + 8);
  puff(p.x, p.y, '#8a7a56', 6, 50);
  if (t.moving && t.fuel > 0) toast('You jumped off a moving train!');
}
function doAct(){
  const p = S.player, t = S.train;
  if (p.aboard){ fallOff(); return; }
  if (canBoard()){
    p.aboard = true;
    p.ly = clamp(trainNear(60) - t.y, 0, trainLen()); p.lx = p.x < 0 ? -20 : 20;
    p.x = p.lx; p.y = t.y + p.ly;
    toast('On deck! Walk to the front cab to drive'); return;
  }
  if (p.atkT <= 0){
    p.atkT = .42; let hitAny = false;
    for (const z of S.zombies){
      const d = Math.hypot(z.x-p.x, z.y-p.y);
      if (d < 52){
        z.hp--; hitAny = true;
        const a = Math.atan2(z.y-p.y, z.x-p.x);
        z.x += Math.cos(a)*26; z.y += Math.sin(a)*26;
        puff(z.x,z.y,'#7a5',5,60);
        if (z.hp <= 0) killZombie(S.zombies.indexOf(z), z.x, z.y, null);
      }
    }
    if (!hitAny) for (const d of propsInView(p.y, 240)){
      if (d.type !== 'debris' || d.taken) continue;
      if (Math.hypot(d.x-p.x, d.y-p.y) < 52){
        d.hp--; hitAny = true; puff(d.x,d.y,'#c9b98a',6,60);
        if (d.hp <= 0){
          d.taken = true;
          if (d.kind === 'log'){ S.inv.wood += 2; addText(d.x,d.y-14,'+2 WOOD','#b8e0a0'); }
          else { S.inv.scrap += 1; S.inv.coal += 1; addText(d.x,d.y-14,'+SCRAP +COAL','#ffe9b0'); }
        }
        break;
      }
    }
    if (hitAny) S.hitFlash = Math.max(S.hitFlash,.25);
  }
}
function doFuel(){
  if (!S.player.aboard){ toast('Climb aboard to fuel up'); return; }
  const t = S.train;
  if (t.fuel > fuelMax() - 5){ toast('Tank is nearly full'); return; }
  if (S.inv.coal > 0){ S.inv.coal--; t.fuel = Math.min(fuelMax(), t.fuel+40);
    addText(0,t.y+40,'+40 FUEL (coal)','#f7d070'); toast('Shovelled coal +40 ⛽'); }
  else if (S.inv.wood > 0){ S.inv.wood--; t.fuel = Math.min(fuelMax(), t.fuel+24);
    addText(0,t.y+40,'+24 FUEL (wood)','#f7d070'); toast('Fed the fire wood +24 ⛽'); }
  else toast('No coal or wood! Get off & forage');
}
function doEat(){
  const p = S.player;
  if (p.aboard){ toast('Eat when you are off the train'); return; }
  if (S.inv.food <= 0){ toast('No canned food'); return; }
  if (p.hp >= 100){ toast('Already at full health'); return; }
  S.inv.food--; p.hp = Math.min(100, p.hp+35); addText(p.x,p.y-18,'+35 HP','#ef6a5a');
  puff(p.x,p.y,'#ef6a5a',6,50);
}
function doTrain(){
  if (!S.player.aboard){ toast('Climb aboard to drive'); return; }
  const t = S.train;
  if (!t.moving){
    if (t.fuel <= 0){ toast('Out of fuel! Refuel first'); return; }
    if (!inCab()){ toast('Walk to the loco cab (front) to drive'); return; }
    t.moving = true; toast('Full steam ahead!');
  } else { t.moving = false; toast('Brakes set'); }
}

/* ---------- cart building ---------- */
function canAfford(cost){ for (const k in cost) if (S.inv[k] < cost[k]) return false; return true; }
function buildCart(type){
  const def = CART_DEFS[type];
  if (!canAfford(def.cost)){ toast('Not enough materials'); return; }
  for (const k in def.cost) S.inv[k] -= def.cost[k];
  S.train.carts.push({ type, store:0, t:0, cool:0, aim:-Math.PI/2 });
  if (type === 'bunker') toast('Coal bunker added — +40 max fuel');
  else toast(def.name + ' added at the rear!');
  puff(0, S.train.y + trainLen() - 40, '#e8d27a', 10, 80);
  if (!document.getElementById('bmodal').classList.contains('hide')) renderBuildList();
}
function renderBuildList(){
  const list = document.getElementById('blist'); list.innerHTML = '';
  for (const type in CART_DEFS){
    const def = CART_DEFS[type];
    let cost = '';
    const icons = { wood:'🪵', coal:'⚫', scrap:'⚙️', food:'🥫' };
    for (const k in def.cost)
      cost += `<i class="${S.inv[k] < def.cost[k] ? 'no' : ''}">${icons[k]}${def.cost[k]}</i>`;
    const el = document.createElement('div'); el.className = 'bitem';
    el.innerHTML = `<div class="ic">${def.icon}</div>
      <div class="info"><b>${def.name}</b><small>${def.desc}</small><div class="cost">${cost}</div></div>
      <button class="bdo ${canAfford(def.cost)?'':'off'}">ADD</button>`;
    el.querySelector('.bdo').onclick = () => buildCart(type);
    list.appendChild(el);
  }
}
function toggleBuild(){
  if (!inZone('workshop')){ toast('Stand inside the workshop car to build'); return; }
  const m = document.getElementById('bmodal');
  if (m.classList.contains('hide')){ renderBuildList(); m.classList.remove('hide'); }
  else m.classList.add('hide');
}
document.getElementById('bclose').onclick = () =>
  document.getElementById('bmodal').classList.add('hide');

/* ---------- update ---------- */
function blocked(x,y){
  const t = S.train;
  // train body
  if (Math.abs(x) < 24 && y > t.y - 8 && y < t.y + trainLen() + 6) return true;
  for (const p of propsInView(y, 260)){
    if (p.type==='tree' && !p.taken && Math.hypot(x-p.x,y-p.y) < 31) return true;
    if (p.type==='rock' && Math.hypot(x-p.x,y-p.y) < 29) return true;
    if (p.type==='debris' && !p.taken && Math.abs(x-p.x)<20 && Math.abs(y-p.y)<16) return true;
    if (p.type==='depot' && x>p.x-75&&x<p.x+75&&y>p.y-52&&y<p.y+52) return true;
  }
  return false;
}
function update(dt){
  S.t += dt;
  S.hitFlash = Math.max(0, S.hitFlash - dt*2.4);
  S.shake = Math.max(0, S.shake - dt*2.2);
  if (S.toastT > 0){ S.toastT -= dt; if (S.toastT <= 0) document.getElementById('toast').style.opacity = 0; }
  const p = S.player, t = S.train;

  /* ----- train motion + track debris ----- */
  if (t.moving && t.fuel > 0){
    t.y -= TRAIN_SPD * dt; t.fuel -= FUEL_DRAIN * dt;
    if (t.fuel <= 0){ t.fuel = 0; t.moving = false; toast('⚠ Out of fuel — the train is stranded'); }
    for (const d of propsInView(t.y, 460)){
      if (d.type !== 'debris' || d.taken) continue;
      if (!d.warn && d.y < t.y - 40 && d.y > t.y - 760){
        d.warn = true; toast('⚠ Debris on the rails ahead!');
      }
      if (d.y > t.y - 34 && d.y < t.y + 12){
        if (hasPlow()){
          d.taken = true; S.inv.scrap++;
          addText(0, d.y, '+1 SCRAP','#9fd39f'); puff(0,d.y,'#c9b98a',9,80);
          S.shake = Math.max(S.shake,.35);
        } else if (!d.thud){
          d.thud = true; t.fuel = Math.max(0, t.fuel-6);
          S.shake = 1; S.hitFlash = .6;
          toast('💥 Debris hit! -6 fuel — build a plow');
        }
      }
    }
    if (Math.random() < dt*22) S.smoke.push({x:(Math.random()*2-1)*4, y:t.y+22, t:1.1, s:8+Math.random()*8});
  }
  if (dist_m() >= GOAL_M && S.mode === 'play'){ S.mode = 'win'; showOverlay('win'); }

  /* ----- player: on deck vs on the ground ----- */
  if (p.aboard){
    let jx = S.joy.dx, jy = S.joy.dy;
    if (S.keys.a||S.keys.ArrowLeft) jx -= 1; if (S.keys.d||S.keys.ArrowRight) jx += 1;
    if (S.keys.w||S.keys.ArrowUp) jy -= 1;   if (S.keys.s||S.keys.ArrowDown) jy += 1;
    const m = Math.hypot(jx,jy); if (m > 1){ jx/=m; jy/=m; }
    const spd = PLAYER_SPD * Math.min(1, m);
    p.lx += jx*spd*dt; p.ly += jy*spd*dt;
    if (m > .1) p.dir = Math.atan2(jy, jx);
    if (Math.abs(p.lx) > 23){ p.lx = clamp(p.lx,-23,23); fallOff(); }
    else if (p.ly < -8){ fallOff(); }
    else if (p.ly > trainLen() + 8){ fallOff(); }
    else { p.x = p.lx; p.y = t.y + p.ly; }
    // cart functions that depend on where you stand
    if (p.aboard){
      if (inZone('medic') && p.hp < 100) p.hp = Math.min(100, p.hp + 2.5*dt);
      const z = zoneAt(p.ly);
      if (z && z.type === 'green' && z.ref.store > 0){
        S.inv.food += z.ref.store;
        addText(p.x, p.y - 18, '+' + z.ref.store + ' FOOD HARVESTED', '#9fd39f');
        toast('Harvested ' + z.ref.store + ' food 🌱'); z.ref.store = 0; z.ref.t = 0;
        puff(p.x, p.y, '#6db35a', 8, 60);
      }
    }
  } else {
    let jx = S.joy.dx, jy = S.joy.dy;
    if (S.keys.a||S.keys.ArrowLeft) jx -= 1; if (S.keys.d||S.keys.ArrowRight) jx += 1;
    if (S.keys.w||S.keys.ArrowUp) jy -= 1;   if (S.keys.s||S.keys.ArrowDown) jy += 1;
    const m = Math.hypot(jx,jy); if (m > 1){ jx/=m; jy/=m; }
    const spd = PLAYER_SPD * Math.min(1, m);
    const nx = p.x + jx*spd*dt, ny = p.y + jy*spd*dt;
    if (!blocked(nx, ny)){ p.x = nx; p.y = ny; }
    else if (!blocked(nx, p.y)) p.x = nx;
    else if (!blocked(p.x, ny)) p.y = ny;
    if (m > .1) p.dir = Math.atan2(jy, jx);
    p.x = clamp(p.x, -560, 560);
    const r = nearestRes(); if (r) collect(r);
    if (t.moving && t.fuel > 0 && Math.abs(p.x) < 26 &&
        p.y > t.y - 34 && p.y < t.y + trainLen() + 10){
      if (p.hurtT <= 0){ damage(18); p.hurtT = .5; }
      p.x = p.x < 0 ? -32 : 32;
    }
  }
  p.hurtT -= dt; p.atkT -= dt;

  /* ----- camera follows the player (rides along on deck) ----- */
  const F = p.aboard ? .60 : .55;
  S.focusF = lerp(S.focusF, F, 1 - Math.pow(.01, dt));
  S.cam.x = lerp(S.cam.x, p.x, 1 - Math.pow(.001, dt));
  S.cam.y = lerp(S.cam.y, p.y, 1 - Math.pow(.001, dt));

  /* ----- cart ticks: greenhouse, turret, ----- */
  for (const s of segs()){
    if (!s.ref) continue;
    if (s.type === 'green'){
      if (t.moving && t.fuel > 0 && s.ref.store < 3){
        s.ref.t += dt;
        if (s.ref.t >= 18){ s.ref.t = 0; s.ref.store++; }
      }
    } else if (s.type === 'turret'){
      const cy = t.y + (s.y0 + s.y1)/2;
      s.ref.cool -= dt;
      let tgt = null, bd = 240;
      for (const z of S.zombies){
        const d = Math.hypot(z.x-0, z.y-cy);
        if (d < bd){ bd = d; tgt = z; }
      }
      if (tgt){
        s.ref.aim = Math.atan2(tgt.y - cy, tgt.x - 0);
        if (s.ref.cool <= 0){
          s.ref.cool = 1.4;
          tgt.hp--;
          const a = s.ref.aim;
          tgt.x += Math.cos(a)*12; tgt.y += Math.sin(a)*12;
          puff(tgt.x, tgt.y, '#7a5', 4, 55);
          S.beams.push({ x1: Math.cos(a)*16, y1: cy + Math.sin(a)*16, x2: tgt.x, y2: tgt.y, t:.12 });
          if (tgt.hp <= 0) killZombie(S.zombies.indexOf(tgt), tgt.x, tgt.y, null);
        }
      }
    }
  }

  zUpdate(dt);

  for (let i = S.parts.length-1; i >= 0; i--){ const q = S.parts[i];
    q.t -= dt; if (q.t <= 0){ S.parts.splice(i,1); continue; }
    q.x += q.vx*dt; q.y += q.vy*dt; q.vx *= .92; q.vy *= .92; }
  for (let i = S.smoke.length-1; i >= 0; i--){ const q = S.smoke[i];
    q.t -= dt; if (q.t <= 0){ S.smoke.splice(i,1); continue; }
    q.y += 26*dt; q.x += Math.sin(q.t*6)*10*dt; q.s += 14*dt; }
  for (let i = S.texts.length-1; i >= 0; i--){ const q = S.texts[i];
    q.t -= dt; q.y -= 34*dt; if (q.t <= 0) S.texts.splice(i,1); }
  for (let i = S.beams.length-1; i >= 0; i--){ S.beams[i].t -= dt;
    if (S.beams[i].t <= 0) S.beams.splice(i,1); }

  uiSync();
}

/* ---------- rendering ---------- */
function rr(x,y,w,h,r){ ctx.beginPath();
  ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r);
  ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath(); }
function fr(x,y,w,h,r,c){ ctx.fillStyle=c; rr(x,y,w,h,r); ctx.fill(); }

function draw(){
  ctx.setTransform(DPR,0,0,DPR,0,0);
  ctx.fillStyle = '#222e1b'; ctx.fillRect(0,0,W,H);
  const ox = W/2 - S.cam.x, oy = H*S.focusF - S.cam.y;
  const shx = (Math.random()-.5)*S.shake*16, shy = (Math.random()-.5)*S.shake*16;
  ctx.save(); ctx.translate(ox+shx, oy+shy);

  const vy0 = S.cam.y - H*0.65, vy1 = S.cam.y + H*0.65;
  const props = propsInView(S.cam.y, 420);

  for (const p of props) if (p.type==='patch'){
    ctx.fillStyle = p.tone < .5 ? 'rgba(44,60,32,.5)' : 'rgba(52,68,36,.45)';
    ctx.beginPath(); ctx.ellipse(p.x, p.y, p.s*1.6, p.s, 0, 0, 6.3); ctx.fill();
  }
  ctx.fillStyle = '#2c2a24'; ctx.fillRect(-46, vy0, 92, vy1-vy0);
  ctx.strokeStyle = '#241f1a'; ctx.lineWidth = 7;
  for (let y = Math.floor(vy0/34)*34; y < vy1; y += 34){
    ctx.beginPath(); ctx.moveTo(-40,y); ctx.lineTo(40,y); ctx.stroke();
  }
  ctx.strokeStyle = '#8a8f96'; ctx.lineWidth = 3.4;
  for (const rx of [-13, 13]){ ctx.beginPath(); ctx.moveTo(rx, vy0); ctx.lineTo(rx, vy1); ctx.stroke(); }
  ctx.strokeStyle = 'rgba(255,240,200,.25)'; ctx.lineWidth = 1;
  for (const rx of [-13, 13]){ ctx.beginPath(); ctx.moveTo(rx, vy0); ctx.lineTo(rx, vy1); ctx.stroke(); }

  for (const p of props){
    if (p.type==='grass'){
      ctx.strokeStyle = '#3e5a30'; ctx.lineWidth = 2;
      for (let i=-1;i<=1;i++){ ctx.beginPath(); ctx.moveTo(p.x+i*4, p.y);
        ctx.lineTo(p.x+i*4 + (p.s-.5)*6, p.y-8-p.s*5); ctx.stroke(); }
    } else if (p.type==='tree' && !p.taken){
      ctx.fillStyle = 'rgba(0,0,0,.3)'; ctx.beginPath(); ctx.ellipse(p.x+5,p.y+7,17,10,0,0,6.3); ctx.fill();
      ctx.fillStyle = '#4a3a26'; ctx.beginPath(); ctx.arc(p.x,p.y,5,0,6.3); ctx.fill();
      ctx.fillStyle = p.s<.5?'#2f5a2a':'#376831';
      ctx.beginPath(); ctx.arc(p.x,p.y,16,0,6.3); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,220,.14)'; ctx.beginPath(); ctx.arc(p.x-5,p.y-5,7,0,6.3); ctx.fill();
    } else if (p.type==='rock'){
      ctx.fillStyle = '#565a5e'; ctx.beginPath();
      ctx.moveTo(p.x-11,p.y+6); ctx.lineTo(p.x-4,p.y-9); ctx.lineTo(p.x+8,p.y-7);
      ctx.lineTo(p.x+12,p.y+5); ctx.closePath(); ctx.fill();
      ctx.fillStyle = 'rgba(255,255,255,.12)'; ctx.beginPath(); ctx.arc(p.x-2,p.y-4,3,0,6.3); ctx.fill();
    } else if (p.type==='depot'){
      ctx.fillStyle = 'rgba(0,0,0,.35)'; ctx.fillRect(p.x-72,p.y-46,150,104);
      ctx.fillStyle = '#6b5a44'; ctx.fillRect(p.x-78,p.y-52,156,104);
      ctx.strokeStyle = '#453a2b'; ctx.lineWidth = 3; ctx.strokeRect(p.x-78,p.y-52,156,104);
      ctx.beginPath(); ctx.moveTo(p.x-84,p.y-52); ctx.lineTo(p.x,p.y-86); ctx.lineTo(p.x+84,p.y-52); ctx.stroke();
      ctx.fillStyle = '#3a3026'; ctx.fillRect(p.x-16,p.y-14,32,60);
      ctx.fillStyle = 'rgba(255,220,140,.5)'; ctx.fillRect(p.x-52,p.y-30,20,18); ctx.fillRect(p.x+32,p.y-30,20,18);
    } else if (p.type==='sign'){
      ctx.fillStyle = '#7a6a4a'; ctx.fillRect(p.x-2,p.y,4,20);
      ctx.fillStyle = '#e8d9a8'; ctx.fillRect(p.x-22,p.y-16,44,18);
      ctx.strokeStyle = '#4a4030'; ctx.strokeRect(p.x-22,p.y-16,44,18);
      ctx.fillStyle = '#3a3226'; ctx.font = '700 11px system-ui'; ctx.textAlign='center';
      ctx.fillText(p.m+' m', p.x, p.y-3);
    } else if (p.type==='finish'){
      ctx.fillStyle = 'rgba(0,0,0,.4)'; ctx.fillRect(-90, p.y-10, 180, 26);
      ctx.fillStyle = '#c93b3b'; ctx.fillRect(-84, p.y-6, 168, 18);
      ctx.fillStyle = '#fff'; ctx.font='800 13px system-ui'; ctx.textAlign='center';
      ctx.fillText('★ STATION AURORA — ' + GOAL_M + ' m ★', 0, p.y+7);
    } else if (['coal','wood','scrap','food'].includes(p.type) && !p.taken){
      drawRes(p);
    } else if (p.type==='debris' && !p.taken){
      drawDebris(p);
    }
  }
  for (const q of S.smoke){ ctx.fillStyle = `rgba(210,210,205,${(q.t/1.1)*.5})`;
    ctx.beginPath(); ctx.arc(q.x, q.y, q.s*.5, 0, 6.3); ctx.fill(); }

  drawTrain();

  for (const b of S.beams){
    ctx.globalAlpha = Math.max(0, b.t/.12);
    ctx.strokeStyle = '#ffd76a'; ctx.lineWidth = 2.5;
    ctx.beginPath(); ctx.moveTo(b.x1,b.y1); ctx.lineTo(b.x2,b.y2); ctx.stroke();
    ctx.fillStyle = '#fff2c0'; ctx.beginPath(); ctx.arc(b.x2,b.y2,2.5,0,6.3); ctx.fill();
  }
  ctx.globalAlpha = 1;

  if (S.player.aboard) drawPlayer(S.player.x, S.player.y, S.player.dir, S.player.atkT);

  for (const z of S.zombies){
    ctx.fillStyle = 'rgba(0,0,0,.3)'; ctx.beginPath(); ctx.ellipse(z.x+3,z.y+6,10,5,0,0,6.3); ctx.fill();
    ctx.fillStyle = '#5d7a44'; ctx.beginPath(); ctx.arc(z.x,z.y,9,0,6.3); ctx.fill();
    ctx.strokeStyle = '#33452a'; ctx.lineWidth = 2; ctx.stroke();
    ctx.fillStyle = '#c33'; const wob = Math.sin(z.t*9)*1.5;
    ctx.fillRect(z.x-4+wob*.3, z.y-4, 2.6, 2.6); ctx.fillRect(z.x+2, z.y-4+wob*.3, 2.6, 2.6);
    ctx.strokeStyle = '#4a6136'; ctx.lineWidth=3;
    ctx.beginPath(); ctx.moveTo(z.x-8,z.y+2+wob); ctx.lineTo(z.x-14,z.y+8+wob); ctx.stroke();
  }

  for (const q of S.parts){ ctx.globalAlpha = Math.min(1, q.t*2);
    ctx.fillStyle = q.c; ctx.beginPath(); ctx.arc(q.x,q.y,3.2,0,6.3); ctx.fill(); }
  ctx.globalAlpha = 1;
  ctx.font = '800 13px system-ui'; ctx.textAlign = 'center';
  for (const q of S.texts){ ctx.globalAlpha = Math.min(1, q.t*2);
    ctx.fillStyle = '#000a'; ctx.fillText(q.txt, q.x+1, q.y+1);
    ctx.fillStyle = q.c; ctx.fillText(q.txt, q.x, q.y); }
  ctx.globalAlpha = 1;

  ctx.restore();

  const vg = ctx.createRadialGradient(W/2,H*.5,H*.42, W/2,H*.5, H*.85);
  vg.addColorStop(0,'rgba(0,0,0,0)'); vg.addColorStop(1,'rgba(0,0,0,.34)');
  ctx.fillStyle = vg; ctx.fillRect(0,0,W,H);
  if (S.hitFlash > 0){
    ctx.fillStyle = `rgba(200,40,30,${S.hitFlash*.3})`; ctx.fillRect(0,0,W,H);
  }
  if (!S.player.aboard && S.mode==='play'){
    const sy = S.train.y + oy;
    if (sy < -30 || sy > H+30){
      const ax = W/2, ay = clamp(sy, 40, H-90), dirn = sy < 0 ? -1 : 1;
      ctx.fillStyle = 'rgba(243,193,75,.92)';
      ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(ax-13, ay+dirn*-16); ctx.lineTo(ax+13, ay+dirn*-16);
      ctx.closePath(); ctx.fill();
      ctx.font='700 12px system-ui'; ctx.textAlign='center'; ctx.fillStyle='#ffe9b0';
      ctx.fillText('🚂 ' + Math.round(Math.abs(S.train.y - S.player.y)/PPM) + ' m', ax, ay+dirn*14);
    }
  }
  if (S.joy.active){
    const j = S.joy;
    ctx.fillStyle = 'rgba(20,26,20,.4)'; ctx.beginPath(); ctx.arc(j.bx,j.by,52,0,6.3); ctx.fill();
    ctx.strokeStyle = 'rgba(240,230,200,.35)'; ctx.lineWidth = 2; ctx.stroke();
    const k = Math.min(1, Math.hypot(j.dx,j.dy)), ka = Math.atan2(j.dy,j.dx);
    ctx.fillStyle = 'rgba(243,193,75,.9)';
    ctx.beginPath(); ctx.arc(j.bx + Math.cos(ka)*k*36, j.by + Math.sin(ka)*k*36, 22, 0, 6.3); ctx.fill();
  }
}

/* ---------- resource / debris art ---------- */
function drawRes(p){
  const {x,y} = p;
  ctx.fillStyle = 'rgba(0,0,0,.28)'; ctx.beginPath(); ctx.ellipse(x+3,y+6,11,5,0,0,6.3); ctx.fill();
  if (p.type === 'coal'){
    ctx.fillStyle = '#23282e';
    for (const [dx,dy] of [[-5,2],[4,-1],[0,-5],[6,4]]){ ctx.beginPath(); ctx.arc(x+dx,y+dy,5,0,6.3); ctx.fill(); }
    ctx.fillStyle = 'rgba(255,255,255,.18)'; ctx.beginPath(); ctx.arc(x-5,y,2,0,6.3); ctx.fill();
  } else if (p.type === 'wood'){
    ctx.fillStyle = '#7a5a34';
    for (let i=0;i<3;i++){ ctx.beginPath(); ctx.roundRect ? ctx.roundRect(x-12, y-8+i*7, 24, 6, 3) : ctx.rect(x-12, y-8+i*7, 24, 6); ctx.fill(); }
    ctx.strokeStyle = '#4a3620'; ctx.lineWidth = 1.4;
    for (let i=0;i<3;i++){ ctx.beginPath(); ctx.moveTo(x-12,y-5+i*7); ctx.lineTo(x+12,y-5+i*7); ctx.stroke(); }
  } else if (p.type === 'scrap'){
    ctx.fillStyle = '#8b929c';
    ctx.fillRect(x-11, y-3, 14, 8); ctx.fillRect(x-2, y-8, 12, 7);
    ctx.fillStyle = '#5a616b'; ctx.fillRect(x-8, y-1, 8, 4); ctx.fillRect(x+2, y-6, 8, 3);
    ctx.strokeStyle = '#c8ced6'; ctx.lineWidth=1; ctx.strokeRect(x-11, y-3, 14, 8);
  } else if (p.type === 'food'){
    ctx.fillStyle = '#b8433a'; ctx.fillRect(x-7, y-9, 14, 17);
    ctx.fillStyle = '#d9d3c4'; ctx.fillRect(x-7, y-4, 14, 5);
    ctx.fillStyle = '#8a2e28'; ctx.fillRect(x-7, y-9, 14, 3);
  }
}
function drawDebris(p){
  const {x,y} = p;
  ctx.fillStyle = 'rgba(0,0,0,.3)'; ctx.beginPath(); ctx.ellipse(x,y+5,22,7,0,0,6.3); ctx.fill();
  if (p.kind === 'log'){
    fr(x-22, y-6, 44, 12, 6, '#7a5a34');
    ctx.fillStyle = '#5a4024'; ctx.beginPath(); ctx.arc(x-20,y,6,0,6.3); ctx.arc(x+20,y,6,0,6.3); ctx.fill();
    ctx.fillStyle = '#8f6c40'; ctx.beginPath(); ctx.arc(x-20,y,3,0,6.3); ctx.arc(x+20,y,3,0,6.3); ctx.fill();
  } else {
    ctx.fillStyle = '#565a5e';
    for (const [dx,dy,r] of [[-10,2,8],[8,-3,7],[0,5,6]]){
      ctx.beginPath(); ctx.arc(x+dx,y+dy,r,0,6.3); ctx.fill(); }
    ctx.fillStyle = 'rgba(255,255,255,.12)'; ctx.beginPath(); ctx.arc(x-11,y,2.6,0,6.3); ctx.fill();
  }
  if (p.warn){
    ctx.globalAlpha = .55 + Math.sin(S.t*9)*.35;
    ctx.fillStyle = '#ff5a4a'; ctx.font='800 17px system-ui'; ctx.textAlign='center';
    ctx.fillText('!', x, y-16); ctx.globalAlpha = 1;
  }
}

/* ---------- train art ---------- */
function wheels(y0,y1){
  ctx.fillStyle = '#14161a';
  for (const wy of [y0+10, y1-10]){
    ctx.beginPath(); ctx.arc(-23,wy,3.6,0,6.3); ctx.arc(23,wy,3.6,0,6.3); ctx.fill(); }
}
function drawPlow(fy){
  ctx.fillStyle = '#8a939e';
  ctx.beginPath(); ctx.moveTo(-25, fy+3); ctx.lineTo(0, fy-27); ctx.lineTo(25, fy+3); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = '#565e66'; ctx.lineWidth = 2.5; ctx.stroke();
  ctx.strokeStyle = 'rgba(30,34,38,.75)'; ctx.lineWidth = 2;
  for (const bx of [-11, 0, 11]){ ctx.beginPath(); ctx.moveTo(bx*.82, fy-22); ctx.lineTo(bx, fy+2); ctx.stroke(); }
  ctx.fillStyle = '#3a4046';
  ctx.beginPath(); ctx.arc(-9, fy-8, 1.8, 0, 6.3); ctx.arc(9, fy-8, 1.8, 0, 6.3); ctx.fill();
  ctx.fillStyle = '#ffe9b0'; ctx.beginPath(); ctx.arc(0, fy-20, 2.6, 0, 6.3); ctx.fill();
}
function drawLoco(ty){
  const y0 = ty, y1 = ty + LOCO_LEN;
  // buffer beam + frame
  fr(-24, y0-4, 48, 12, 3, '#7a2e28');
  // boiler
  fr(-22, y0+6, 44, 92, 12, '#384046');
  ctx.strokeStyle = '#22262a'; ctx.lineWidth = 2; rr(-22, y0+6, 44, 92, 12); ctx.stroke();
  // gold bands + rivets
  ctx.strokeStyle = 'rgba(243,193,75,.55)'; ctx.lineWidth = 2;
  for (const by of [y0+28, y0+56, y0+84]){ ctx.beginPath(); ctx.moveTo(-21,by); ctx.lineTo(21,by); ctx.stroke(); }
  ctx.fillStyle = 'rgba(255,255,255,.16)';
  for (const ry of [y0+16, y0+44, y0+72]){
    ctx.beginPath(); ctx.arc(-18,ry,1.6,0,6.3); ctx.arc(18,ry,1.6,0,6.3); ctx.fill(); }
  // running boards
  ctx.fillStyle = '#565e66'; ctx.fillRect(-27, y0+10, 4, 84); ctx.fillRect(23, y0+10, 4, 84);
  // chimney + steam dome
  ctx.fillStyle = '#20242a'; ctx.beginPath(); ctx.arc(0, y0+13, 8.5, 0, 6.3); ctx.fill();
  ctx.fillStyle = '#101316'; ctx.beginPath(); ctx.arc(0, y0+13, 5, 0, 6.3); ctx.fill();
  ctx.fillStyle = '#9aa3ad'; ctx.beginPath(); ctx.arc(0, y0+44, 7, 0, 6.3); ctx.fill();
  ctx.strokeStyle = '#565e66'; ctx.lineWidth = 1.5; ctx.stroke();
  // sandbox
  fr(-7, y0+62, 14, 12, 4, '#4a5158');
  // cab
  fr(-23, y0+96, 46, 54, 5, '#454b52');
  fr(-26, y0+100, 52, 48, 6, '#2b2f34');
  ctx.fillStyle = 'rgba(255,214,120,.8)';
  ctx.fillRect(-14, y0+108, 11, 14); ctx.fillRect(3, y0+108, 11, 14);
  ctx.strokeStyle = '#1b1e21'; ctx.lineWidth = 2; rr(-26, y0+100, 52, 48, 6); ctx.stroke();
  wheels(y0, y1);
}
function drawTender(y0, y1){
  fr(-21, y0, 42, y1-y0, 4, '#33383e');
  ctx.strokeStyle = '#22262a'; ctx.lineWidth = 2; rr(-21, y0, 42, y1-y0, 4); ctx.stroke();
  // coal heap scaled by fuel
  const fr_ = S.train.fuel / fuelMax();
  const heapH = 8 + fr_ * 30;
  ctx.fillStyle = '#171a1e';
  ctx.beginPath(); ctx.moveTo(-16, y1-8);
  ctx.quadraticCurveTo(-8, y1-8-heapH, 0, y1-8-heapH*.7);
  ctx.quadraticCurveTo(8, y1-8-heapH, 16, y1-8); ctx.closePath(); ctx.fill();
  if (fr_ > .15){ ctx.fillStyle = 'rgba(130,140,160,.4)';
    ctx.beginPath(); ctx.arc(-6, y1-14-heapH*.5, 1.8, 0, 6.3); ctx.fill(); }
  // side ladder
  ctx.strokeStyle = '#565e66'; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(-18, y0+10); ctx.lineTo(-18, y0+52); ctx.stroke();
  for (const ly of [y0+18, y0+32, y0+46]){ ctx.beginPath(); ctx.moveTo(-21,ly); ctx.lineTo(-15,ly); ctx.stroke(); }
  wheels(y0, y1);
}
function drawCart(s, ty){
  const y0 = ty + s.y0, y1 = ty + s.y1, my = (y0+y1)/2;
  wheels(y0, y1);
  if (s.type === 'workshop'){
    fr(-22, y0, 44, y1-y0, 3, '#7a4632');
    ctx.strokeStyle = '#5c3526'; ctx.lineWidth = 1.6;
    for (let py = y0+10; py < y1; py += 9){ ctx.beginPath(); ctx.moveTo(-21,py); ctx.lineTo(21,py); ctx.stroke(); }
    // open roof hatch with warm light
    ctx.fillStyle = '#2b2026'; ctx.fillRect(-10, y0+12, 20, 26);
    ctx.fillStyle = 'rgba(247,208,112,.85)'; ctx.fillRect(-7, y0+15, 14, 20);
    ctx.fillStyle = 'rgba(247,208,112,.25)'; ctx.fillRect(-16, y0+9, 32, 34);
    ctx.strokeStyle = '#3f2a1e'; ctx.lineWidth = 2; ctx.strokeRect(-10, y0+12, 20, 26);
    // painted wrench plate
    ctx.fillStyle = '#e8e4da'; ctx.fillRect(9, y1-18, 11, 11);
    ctx.fillStyle = '#5c3526'; ctx.font='800 9px system-ui'; ctx.textAlign='center';
    ctx.fillText('🔧', 14.5, y1-9.5);
  } else if (s.type === 'bunker'){
    fr(-21, y0, 42, y1-y0, 3, '#23282e');
    ctx.fillStyle = '#14171b'; ctx.fillRect(-17, y0+8, 34, y1-y0-16);
    ctx.fillStyle = '#1d2126';
    for (const [dx,dy] of [[-8,y0+22],[8,y0+24],[0,y0+36],[-7,y0+46],[8,y0+46]]){
      ctx.beginPath(); ctx.arc(dx,dy,6,0,6.3); ctx.fill(); }
    ctx.fillStyle = 'rgba(150,160,180,.35)';
    ctx.beginPath(); ctx.arc(-9,y0+20,1.7,0,6.3); ctx.arc(7,y0+22,1.7,0,6.3); ctx.fill();
    // hazard stripes
    for (let i=0;i<5;i++){ ctx.fillStyle = i%2 ? '#e8b83a' : '#1a1d21';
      ctx.fillRect(-20+i*8.4, y0+2, 8.4, 4); }
  } else if (s.type === 'green'){
    fr(-21, y0, 42, y1-y0, 4, '#d8d8d0');
    ctx.fillStyle = 'rgba(150,215,255,.30)'; ctx.fillRect(-17, y0+4, 34, y1-y0-8);
    ctx.strokeStyle = 'rgba(255,255,255,.5)'; ctx.lineWidth = 1.4;
    for (const py of [y0+22, y0+38]){ ctx.beginPath(); ctx.moveTo(-17,py+6); ctx.lineTo(17,py-6); ctx.stroke(); }
    // planters + plants (grow with store)
    ctx.fillStyle = '#4a3a26'; ctx.fillRect(-15, y0+14, 12, 34); ctx.fillRect(3, y0+14, 12, 34);
    const g = s.ref ? s.ref.store + (s.ref.store < 3 ? s.ref.t/18 : 0) : 0;
    ctx.fillStyle = '#4f8f3f';
    for (let i=0;i<Math.min(3,Math.ceil(g));i++){
      const r0 = 2 + g*1.2;
      ctx.beginPath(); ctx.arc(-9, y0+22+i*11, r0, 0, 6.3); ctx.arc(9, y0+22+i*11, r0, 0, 6.3); ctx.fill();
    }
    ctx.strokeStyle = '#9aa39c'; ctx.lineWidth = 2; rr(-21, y0, 42, y1-y0, 4); ctx.stroke();
  } else if (s.type === 'turret'){
    fr(-21, y0, 42, y1-y0, 3, '#4a4f55');
    ctx.strokeStyle = '#33383e'; ctx.lineWidth = 1.5;
    for (let py = y0+9; py < y1; py += 9){ ctx.beginPath(); ctx.moveTo(-20,py); ctx.lineTo(20,py); ctx.stroke(); }
    // sandbag ring
    ctx.fillStyle = '#8a7a56';
    for (let i=0;i<8;i++){ const a = i/8*6.28;
      ctx.beginPath(); ctx.ellipse(Math.cos(a)*15, my+Math.sin(a)*15, 5, 3.6, a, 0, 6.3); ctx.fill(); }
    // rotating gun
    ctx.fillStyle = '#33383e'; ctx.beginPath(); ctx.arc(0,my,11,0,6.3); ctx.fill();
    ctx.strokeStyle = '#22262a'; ctx.lineWidth = 2; ctx.stroke();
    ctx.save(); ctx.translate(0,my); ctx.rotate(s.ref ? s.ref.aim : -Math.PI/2);
    ctx.fillStyle = '#22262a'; ctx.fillRect(0,-2.6,22,5.2);
    ctx.fillStyle = '#101316'; ctx.fillRect(18,-3.4,4,6.8);
    ctx.restore();
    ctx.fillStyle = '#6b5a34'; ctx.fillRect(-17,y0+4,9,7); ctx.fillRect(8,y0+4,9,7);
  } else if (s.type === 'medic'){
    fr(-21, y0, 42, y1-y0, 3, '#e8e4da');
    ctx.fillStyle = '#c93b3b'; ctx.fillRect(-21, y0+2, 42, 6);
    ctx.fillRect(-4, my-13, 8, 26); ctx.fillRect(-13, my-4, 26, 8);
    ctx.strokeStyle = '#b8b4aa'; ctx.lineWidth = 2; rr(-21, y0, 42, y1-y0, 3); ctx.stroke();
    ctx.fillStyle = '#8a8a82';
    ctx.beginPath(); ctx.arc(-17,y0+8,1.8,0,6.3); ctx.arc(17,y0+8,1.8,0,6.3);
    ctx.arc(-17,y1-8,1.8,0,6.3); ctx.arc(17,y1-8,1.8,0,6.3); ctx.fill();
  }
}
function drawTrain(){
  const t = S.train, L = trainLen();
  ctx.fillStyle = 'rgba(0,0,0,.35)'; ctx.fillRect(-28, t.y-8, 56, L+16);
  const ss = segs();
  ctx.fillStyle = '#14161a';
  for (let i=1;i<ss.length;i++) ctx.fillRect(-13, t.y+ss[i].y0-COUP, 26, COUP);
  if (hasPlow()) drawPlow(t.y);
  for (const s of ss){
    if (s.type==='loco') drawLoco(t.y);
    else if (s.type==='tender') drawTender(t.y+TENDER0, t.y+TENDER0+CART_LEN);
    else drawCart(s, t.y);
  }
  const rear = t.y + L - 5;
  ctx.fillStyle = 'rgba(255,70,60,.3)'; ctx.beginPath(); ctx.arc(0,rear,7,0,6.3); ctx.fill();
  ctx.fillStyle = '#ff5a4a'; ctx.beginPath(); ctx.arc(0,rear,3.2,0,6.3); ctx.fill();
  if (t.moving && t.fuel > 0){
    const fy = t.y - (hasPlow() ? 30 : 6);
    const g = ctx.createLinearGradient(0, fy, 0, fy-135);
    g.addColorStop(0,'rgba(255,236,180,.30)'); g.addColorStop(1,'rgba(255,236,180,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.moveTo(-16, fy); ctx.lineTo(16, fy);
    ctx.lineTo(30, fy-135); ctx.lineTo(-30, fy-135); ctx.closePath(); ctx.fill();
    ctx.fillStyle = '#ffe9b0'; ctx.beginPath(); ctx.arc(0, fy-2, 3.6, 0, 6.3); ctx.fill();
  }
}

/* ---------- HUD sync ---------- */
const $ = id => document.getElementById(id);
let uiT = 0;
function uiSync(){
  if (S.t - uiT < .12) return; uiT = S.t;
  if (new URLSearchParams(location.search).has('probe'))
    document.title = `aboard=${S.player.aboard} ly=${S.player.ly|0} carts=${S.train.carts.map(c=>c.type).join(',')} ` +
      `fuel=${S.train.fuel|0}/${fuelMax()} inv=${JSON.stringify(S.inv)} mode=${S.mode}`;
  $('fuelF').style.width = (S.train.fuel/fuelMax()*100) + '%';
  $('hpF').style.width = S.player.hp + '%';
  $('dist').textContent = Math.floor(dist_m()) + ' / ' + GOAL_M + ' m';
  const i = S.inv;
  $('inv').innerHTML =
    `<span class="chip">🪵 ${i.wood}</span><span class="chip">⚫ ${i.coal}</span>`+
    `<span class="chip">⚙️ ${i.scrap}</span><span class="chip">🥫 ${i.food}</span>`+
    `<span class="chip">🚃 ${1 + S.train.carts.length}</span>`;
  $('bEat').querySelector('span').textContent = i.food;
  $('bEat').classList.toggle('off', i.food <= 0 || S.player.aboard);
  $('bTrain').querySelector('span').textContent =
    S.train.moving ? 'STOP' : (S.train.fuel > 0 ? (inCab() ? 'GO' : 'CAB') : 'NO FUEL');
  $('bTrain').classList.toggle('off', !S.player.aboard);
  $('bFuel').classList.toggle('off', !S.player.aboard || (S.inv.coal<=0 && S.inv.wood<=0));
  $('bBuild').classList.toggle('off', !inZone('workshop'));
  const a = $('bAct');
  if (S.player.aboard){ a.querySelector('em').textContent='👇'; a.querySelector('span').textContent='GET OFF'; a.classList.remove('off'); }
  else if (canBoard()){ a.querySelector('em').textContent='🚂'; a.querySelector('span').textContent='BOARD'; a.classList.remove('off'); }
  else { a.querySelector('em').textContent='🔨'; a.querySelector('span').textContent='HIT'; a.classList.remove('off'); }
}

/* ---------- overlays ---------- */
function showOverlay(kind){
  const ov = $('ov'), c = $('ovCard');
  if (kind === 'title'){
    c.innerHTML = `<h1>IRON HAUL</h1>
      <p style="color:#f3c14b;font-weight:700">Drive the loot train to Station Aurora</p>
      <p>The train burns fuel as it rolls. <b>STOP</b>, hop off and forage
      coal · wood · food · scrap. The infected wait at every depot — and debris
      blocks the rails.</p>
      <p>Walk around your train <b>even while it rolls</b>. Stand in the
      <b>workshop car</b> to bolt on new cars: plow, bunker, greenhouse,
      turret, infirmary.</p>
      <p>Reach the <b>${GOAL_M} m</b> mark alive.</p>
      <button id="go">START THE ENGINE</button>
      <div class="keys">MOBILE: left-thumb joystick · buttons on the right<br>
      DESKTOP: WASD move · SPACE act · F fuel · E eat · T train · B build</div>`;
  } else if (kind === 'win'){
    c.innerHTML = `<h2 style="color:#f3c14b">🚂 STATION AURORA!</h2>
      <div class="big">🎉</div>
      <div class="stat"><span>Distance</span><b>${Math.floor(dist_m())} m</b></div>
      <div class="stat"><span>Cars in the consist</span><b>${1 + S.train.carts.length}</b></div>
      <div class="stat"><span>Wood</span><b>${S.inv.wood}</b></div>
      <div class="stat"><span>Coal</span><b>${S.inv.coal}</b></div>
      <div class="stat"><span>Scrap</span><b>${S.inv.scrap}</b></div>
      <div class="stat"><span>Health</span><b>${Math.round(S.player.hp)}</b></div>
      <button id="go" style="margin-top:14px">RUN IT AGAIN</button>`;
  } else if (kind === 'dead'){
    c.innerHTML = `<h2 style="color:#ef6a5a">☠ YOU DIED</h2>
      <div class="big">💀</div>
      <div class="stat"><span>Reached</span><b>${Math.floor(dist_m())} / ${GOAL_M} m</b></div>
      <div class="stat"><span>Scrap hauled</span><b>${S.inv.scrap}</b></div>
      <div class="stat"><span>Cars built</span><b>${S.train.carts.length}</b></div>
      <button id="go" style="margin-top:14px">TRY AGAIN</button>`;
  }
  ov.classList.remove('hide');
  $('go').onclick = () => { reset(); ov.classList.add('hide'); };
}
function reset(){
  S.mode = 'play'; S.t = 0;
  S.train = { y: 0, moving: true, fuel: 55, carts: [] };
  S.inv = { wood: 2, coal: 2, scrap: 2, food: 1 };
  S.player = { x: 0, y: 120, lx: 0, ly: 120, aboard: true, hp: 100,
               dir: -Math.PI/2, atkT: 0, hurtT: 0 };
  S.cam = { x: 0, y: 0 }; S.focusF = .6;
  S.zombies = []; S.parts = []; S.texts = []; S.smoke = []; S.beams = [];
  for (const [, list] of chunks) for (const p of list) delete p.taken;
  toast('Rolling! Keep an eye on ⛽');
}

/* ---------- input ---------- */
function act(x,y){
  if (S.mode !== 'play') return;
  if (y === 'train') doTrain(); else if (y === 'fuel') doFuel();
  else if (y === 'eat') doEat(); else if (y === 'build') toggleBuild();
  else doAct();
}
$('bTrain').addEventListener('pointerdown', e => { e.preventDefault(); act(0,'train'); });
$('bFuel').addEventListener('pointerdown', e => { e.preventDefault(); act(0,'fuel'); });
$('bBuild').addEventListener('pointerdown', e => { e.preventDefault(); act(0,'build'); });
$('bEat').addEventListener('pointerdown', e => { e.preventDefault(); act(0,'eat'); });
$('bAct').addEventListener('pointerdown', e => { e.preventDefault(); act(0,'act'); });

cv.addEventListener('pointerdown', e => {
  if (e.clientX < W * 0.62 && S.mode === 'play'){
    S.joy.active = true; S.joy.id = e.pointerId;
    S.joy.bx = e.clientX; S.joy.by = e.clientY; S.joy.dx = 0; S.joy.dy = 0;
    cv.setPointerCapture(e.pointerId);
  }
});
cv.addEventListener('pointermove', e => {
  if (S.joy.active && e.pointerId === S.joy.id){
    let dx = e.clientX - S.joy.bx, dy = e.clientY - S.joy.by;
    const d = Math.hypot(dx,dy), max = 52;
    if (d > max){ dx = dx/d*max; dy = dy/d*max; }
    S.joy.dx = dx/max; S.joy.dy = dy/max;
  }
});
function joyEnd(e){ if (S.joy.active && e.pointerId === S.joy.id){
  S.joy.active = false; S.joy.dx = 0; S.joy.dy = 0; } }
cv.addEventListener('pointerup', joyEnd); cv.addEventListener('pointercancel', joyEnd);

window.addEventListener('keydown', e => {
  S.keys[e.key] = true;
  if (S.mode !== 'play'){ if (e.key===' '||e.key==='Enter') $('go')?.click(); return; }
  if (e.key === ' ') { e.preventDefault(); act(0,'act'); }
  if (e.key === 'f' || e.key === 'F') act(0,'fuel');
  if (e.key === 'e' || e.key === 'E') act(0,'eat');
  if (e.key === 't' || e.key === 'T') act(0,'train');
  if (e.key === 'b' || e.key === 'B') act(0,'build');
});
window.addEventListener('keyup', e => S.keys[e.key] = false);
document.addEventListener('gesturestart', e => e.preventDefault());
document.addEventListener('dblclick', e => e.preventDefault());

/* ---------- debug hooks for automated screenshots ---------- */
const q = new URLSearchParams(location.search);
if (q.has('shot')){
  S.mode = 'play';
  if (q.get('shot') === 'off'){
    S.train.moving = false; S.player.aboard = false; S.player.x = 120; S.player.y = -240;
    S.train.fuel = 40; S.inv = { wood:2, coal:1, scrap:1, food:2 };
  } else if (q.get('shot') === 'zom'){
    S.train.moving = false; S.player.aboard = false; S.player.x = 150; S.player.y = -260;
    spawnZs({ x: 90, y: -300, n: 4 });
  } else if (q.get('shot') === 'deck'){
    S.train.moving = true;
    for (const ty of ['workshop','bunker','green','turret','medic'])
      S.train.carts.push({ type:ty, store: ty==='green'?2:0, t: ty==='green'?9:0, cool:0, aim:-Math.PI/2 });
    S.player.aboard = true; S.player.lx = 6; S.player.ly = 330;
    S.inv = { wood:3, coal:2, scrap:4, food:1 }; S.train.fuel = 70;
  } else if (q.get('shot') === 'build'){
    S.train.moving = false;
    S.train.carts.push({ type:'workshop', store:0, t:0, cool:0, aim:-Math.PI/2 });
    S.player.aboard = true; S.player.lx = 0; S.player.ly = TENDER0 + CART_LEN + COUP + 30;
    S.inv = { wood:9, coal:3, scrap:7, food:2 };
    renderBuildList(); document.getElementById('bmodal').classList.remove('hide');
  } else if (q.get('shot') === 'win'){ S.mode='win'; showOverlay('win'); }
  else if (q.get('shot') === 'dead'){ damage(120); }
  else { S.player.aboard = true; S.player.lx = 0; S.player.ly = 120; }
  const n = parseInt(q.get('sim') || '90', 10);
  for (let i = 0; i < n; i++) { try { update(1/60); } catch(e){} }
}

/* ---------- boot ---------- */
if (!q.has('shot')) showOverlay('title');
let last = performance.now();
function frame(now){
  const dt = Math.min(.05, (now - last)/1000); last = now;
  try { if (S.mode === 'play') update(dt); else { S.t += dt; } }
  catch (err) { document.title = 'ERR-U: ' + err.message + ' @ ' + (err.stack||'').split('\n')[1]; }
  try { draw(); }
  catch (err) { document.title = 'ERR-D: ' + err.message + ' @ ' + (err.stack||'').split('\n')[1]; }
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

