const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  const base = 'file://' + path.resolve('index.html');
  const shots = process.argv.slice(2);
  for (const s of shots) {
    const url = base + (s === 'title' ? '' : '?shot=' + s + '&sim=60');
    await page.goto(url);
    await page.waitForTimeout(700);
    const title = await page.title();
    await page.screenshot({ path: `/tmp/opencode/${s}.png` });
    console.log(s, '|', title);
  }
  await browser.close();
  if (errors.length) console.log(errors.join('\n'));
})();

const { chromium } = require('playwright');
const path = require('path');
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('file://' + path.resolve('index.html'));
  await page.waitForTimeout(500);

  // title + start
  assert(await page.locator('#ov').isVisible(), 'title overlay visible');
  await page.click('#go');
  await page.waitForTimeout(300);
  assert(!(await page.locator('#ov').isVisible()), 'title overlay dismissed');
  assert(await page.evaluate(() => S.mode === 'play' && S.player.aboard), 'playing and aboard');

  // build button should open even without workshop
  await page.keyboard.press('b');
  await page.waitForTimeout(250);
  assert(await page.locator('#bmodal').isVisible(), 'BUILD opens without existing workshop');
  const listCount = await page.locator('.bitem').count();
  assert(listCount === 6, 'all 6 cart entries listed');
  const enabled = await page.$$eval('.bdo', bs => bs.map(b => !b.classList.contains('off')));
  console.log('enabled ADD buttons at start:', enabled);
  await page.screenshot({ path: '/tmp/opencode/t-build-open.png' });

  // close modal
  await page.click('#bclose');
  assert(!(await page.locator('#bmodal').isVisible()), 'build modal closes');

  // stop the train while aboard
  await page.keyboard.press('t');
  await page.waitForTimeout(200);
  assert(await page.evaluate(() => !S.train.moving), 'STOP brakes train while aboard');

  // walk down to workshop zone after cheating in a workshop (tests zone access)
  await page.evaluate(() => {
    S.train.carts.push({ type: 'workshop', store: 0, t: 0, cool: 0, aim: -Math.PI / 2 });
    S.inv = { wood: 20, coal: 10, scrap: 20, food: 5 };
  });
  await page.keyboard.down('ArrowDown');
  await page.waitForTimeout(900);
  await page.keyboard.up('ArrowDown');
  const z = await page.evaluate(() => ({ ly: Math.round(S.player.ly), inz: inZone('workshop'), open: canOpenBuild() }));
  console.log('after walking:', z);
  assert(z.ly > 225, 'walked to workshop car');
  assert(z.inz, 'detected inside workshop');
  assert(z.open, 'build allowed inside workshop');

  // build a plow from inside the workshop
  await page.keyboard.press('b');
  await page.waitForTimeout(200);
  const plowIdx = await page.evaluate(() => Object.keys(CART_DEFS).indexOf('plow'));
  await page.locator('.bitem').nth(plowIdx).locator('.bdo').click();
  await page.waitForTimeout(300);
  const after = await page.evaluate(() => ({ carts: S.train.carts.map(c => c.type), inv: S.inv, modal: !document.getElementById('bmodal').classList.contains('hide') }));
  console.log('after build:', after);
  assert(after.carts.includes('plow'), 'plow built');
  assert(after.modal, 'modal stays open after building');
  await page.screenshot({ path: '/tmp/opencode/t-built.png' });
  await page.click('#bclose');

  // drive from cab
  await page.keyboard.down('ArrowUp');
  await page.waitForTimeout(800);
  await page.keyboard.up('ArrowUp');
  const cab = await page.evaluate(() => ({ ly: Math.round(S.player.ly), inCab: inCab() }));
  console.log('cab:', cab);
  assert(cab.inCab, 'reached cab');
  await page.keyboard.press('t');
  await page.waitForTimeout(200);
  assert(await page.evaluate(() => S.train.moving), 'GO starts train from cab');

  // debark while moving (should fall/jump off)
  await page.keyboard.press(' ');
  await page.waitForTimeout(200);
  assert(await page.evaluate(() => !S.player.aboard), 'GET OFF leaves the train');
  await page.screenshot({ path: '/tmp/opencode/t-onground.png' });

  // no boarding a moving train
  const boardMoving = await page.evaluate(() => { S.player.x = 0; S.player.y = S.train.y + 120; return canBoard(); });
  assert(!boardMoving, 'cannot board a moving train');

  // stop via direct state, then board
  await page.evaluate(() => { S.train.moving = false; S.player.x = 25; S.player.y = S.train.y + 120; });
  const boardStopped = await page.evaluate(() => canBoard());
  assert(boardStopped, 'can board a stopped nearby train');
  await page.keyboard.press(' ');
  await page.waitForTimeout(200);
  assert(await page.evaluate(() => S.player.aboard), 'boarded the stopped train');

  // off-train resource collection
  await page.evaluate(() => { S.train.moving = false; S.player.aboard = false; S.player.x = 0; S.player.y = S.train.y - 300; });
  const res = await page.evaluate(() => {
    const p = propsInView(S.player.y, 400).find(p => !p.taken && ['wood','coal','scrap','food','tree'].includes(p.type));
    if (!p) return null;
    S.player.x = p.x; S.player.y = p.y;
    const before = JSON.stringify(S.inv);
    collect(p);
    return { type: p.type, before, after: JSON.stringify(S.inv) };
  });
  console.log('collected:', res);
  assert(res && res.before !== res.after, 'resource collection changes inventory');

  // eat / heal
  const eat = await page.evaluate(() => {
    S.inv.food = 2; S.player.hp = 40; S.player.aboard = false;
    doEat(); return { hp: S.player.hp, food: S.inv.food };
  });
  assert(eat.hp === 75 && eat.food === 1, 'eating food heals 35');

  // fuel
  const fuel = await page.evaluate(() => {
    S.player.aboard = true; S.train.fuel = 20; S.inv.coal = 2; S.inv.wood = 2;
    doFuel(); return { fuel: S.train.fuel, coal: S.inv.coal };
  });
  assert(fuel.fuel === 60 && fuel.coal === 1, 'coal refuels +40');

  // win state
  const win = await page.evaluate(() => {
    S.mode = 'play'; S.train.y = -GOAL_M * PPM + 1; S.train.moving = true;
    update(0.016); return { mode: S.mode, title: document.querySelector('#ovCard h2')?.textContent };
  });
  await page.waitForTimeout(200);
  console.log('win:', win);
  assert(win.mode === 'win', 'reaching 3000 m wins');
  await page.screenshot({ path: '/tmp/opencode/t-win.png' });

  // death
  await page.evaluate(() => { document.getElementById('ov').classList.add('hide'); S.mode = 'play'; S.player.hp = 5; damage(10); });
  await page.waitForTimeout(300);
  assert(await page.evaluate(() => S.mode === 'dead'), 'hp 0 triggers death');
  await page.screenshot({ path: '/tmp/opencode/t-dead.png' });

  // retry resets
  await page.click('#go');
  await page.waitForTimeout(300);
  const resetState = await page.evaluate(() => ({ mode: S.mode, carts: S.train.carts.length, hp: S.player.hp, aboard: S.player.aboard, y: S.train.y }));
  console.log('after retry:', resetState);
  assert(resetState.mode === 'play' && resetState.carts === 0 && resetState.hp === 100 && resetState.aboard, 'retry fully resets the run');

  console.log(errors.length ? 'ERRORS:\n' + errors.join('\n') : 'no page errors');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

