const { chromium } = require('playwright');
const path = require('path');
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('file://' + path.resolve('index.html'));
  await page.waitForTimeout(500);
  await page.click('#go');
  await page.waitForTimeout(250);

  // start with workshop parts
  const start = await page.evaluate(() => ({ inv: S.inv, cab: S.train.carts.length }));
  console.log('start:', start);
  assert(start.inv.wood >= 6 && start.inv.scrap >= 4, 'starts with workshop parts');
  assert(start.cab === 0, 'starts with no carts');

  // BUILD at the cab: first workshop only
  await page.keyboard.press('b');
  await page.waitForTimeout(200);
  assert(await page.locator('#bmodal').isVisible(), 'build modal opens');
  const note1 = await page.locator('#bnote').innerText();
  console.log('note:', note1);
  assert(/WORKSHOP first/.test(note1), 'first-build hint shown');
  const enabled = await page.$$eval('.bdo', bs => bs.map(b => !b.classList.contains('off')));
  assert(JSON.stringify(enabled) === JSON.stringify([true, false, false, false, false, false]), 'only workshop affordable/enabled');
  await page.screenshot({ path: '/tmp/opencode/f-build-start.png' });

  // buy workshop -> modal auto closes, game unpauses
  await page.locator('.bitem').first().locator('.bdo').click();
  await page.waitForTimeout(250);
  const built = await page.evaluate(() => ({ carts: S.train.carts.map(c => c.type), inv: S.inv, paused: S.paused, modal: !document.getElementById('bmodal').classList.contains('hide') }));
  console.log('built:', built);
  assert(built.carts[0] === 'workshop', 'workshop built');
  assert(!built.modal && !built.paused, 'modal closes after first workshop');

  // walk back into workshop
  await page.keyboard.down('ArrowDown');
  await page.waitForTimeout(850);
  await page.keyboard.up('ArrowDown');
  const zone = await page.evaluate(() => ({ ly: Math.round(S.player.ly), inz: inZone('workshop'), open: canOpenBuild() }));
  console.log('zone:', zone);
  assert(zone.inz && zone.open, 'workshop zone detected and build allowed');

  await page.evaluate(() => { S.inv = { wood: 30, coal: 20, scrap: 30, food: 5 }; });
  await page.keyboard.press('b');
  await page.waitForTimeout(200);
  const items = await page.$$eval('.bitem b', bs => bs.map(b => b.textContent));
  console.log('catalogue:', items);
  assert(items.length === 5 && !items.includes('WORKSHOP'), 'workshop removed from catalogue once owned');
  const note2 = await page.locator('#bnote').innerText();
  assert(/Workshop active/.test(note2), 'active workshop note shown');
  await page.screenshot({ path: '/tmp/opencode/f-build-catalogue.png' });

  // build plow (first entry now)
  await page.locator('.bitem').first().locator('.bdo').click();
  await page.waitForTimeout(250);
  assert(await page.evaluate(() => S.train.carts.some(c => c.type === 'plow')), 'plow built from workshop');

  // pause while modal is open
  const y1 = await page.evaluate(() => { S.train.moving = true; S.train.fuel = 80; return S.train.y; });
  await page.waitForTimeout(500);
  const y2 = await page.evaluate(() => S.train.y);
  assert(Math.abs(y2 - y1) < 1, 'game is paused while build modal is open');
  await page.click('#bclose');
  await page.waitForTimeout(500);
  const y3 = await page.evaluate(() => S.train.y);
  console.log('train y paused/resumed:', y1.toFixed(1), y2.toFixed(1), y3.toFixed(1));
  assert(y3 < y2 - 5, 'train resumes after closing modal');

  // jump onto moving train
  const jump = await page.evaluate(() => {
    S.train.moving = true; S.train.fuel = 70;
    S.player.aboard = false; S.player.ly = 0; S.player.x = 32; S.player.y = S.train.y + 100;
    return { can: canBoard(), moving: S.train.moving };
  });
  console.log('jump:', jump);
  assert(jump.can, 'boarding offered for nearby moving train');
  await page.keyboard.press(' ');
  await page.waitForTimeout(200);
  assert(await page.evaluate(() => S.player.aboard), 'jumped onto moving train');
  const actLabel = await page.locator('#bAct span').innerText();
  assert(actLabel === 'GET OFF', 'action button shows GET OFF aboard');

  // low fuel warning
  const low = await page.evaluate(() => {
    S.train.moving = true; S.train.fuel = 21; S.lowFuel = false;
    for (let i = 0; i < 60; i++) update(1 / 60);
    return { fuel: S.train.fuel, lowFuel: S.lowFuel };
  });
  console.log('low fuel:', low);
  assert(low.lowFuel && low.fuel < 20, 'low fuel warning fires');

  // brake from cab & drive again
  await page.evaluate(() => { S.player.ly = 120; S.train.moving = false; });
  await page.keyboard.press('t');
  await page.waitForTimeout(150);
  assert(await page.evaluate(() => S.train.moving), 'GO from cab starts the train');

  // win + retry
  await page.evaluate(() => { S.train.y = -GOAL_M * PPM - 1; update(1 / 60); });
  await page.waitForTimeout(200);
  assert(await page.evaluate(() => S.mode === 'win'), 'win at 3000 m');
  await page.click('#go');
  await page.waitForTimeout(200);
  const rr = await page.evaluate(() => ({ mode: S.mode, carts: S.train.carts.length, inv: S.inv, hp: S.player.hp }));
  console.log('retry:', rr);
  assert(rr.mode === 'play' && rr.carts === 0 && rr.hp === 100 && rr.inv.wood === 6, 'retry resets cleanly');

  // every debug scene still renders
  for (const s of ['deck', 'build', 'off', 'zom', 'plow', 'win', 'dead']) {
    await page.goto('file://' + path.resolve('index.html') + '?shot=' + s + '&sim=60');
    await page.waitForTimeout(250);
    const err = await page.title();
    assert(!err.startsWith('ERR'), 'scene ' + s + ' renders');
  }

  console.log(errors.length ? 'ERRORS:\n' + errors.join('\n') : 'no page errors');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  const base = 'file://' + path.resolve('index.html');
  await page.goto(base);
  await page.waitForTimeout(500);
  await page.screenshot({ path: '/tmp/opencode/f-title.png' });

  await page.click('#go');
  await page.waitForTimeout(1200);
  await page.screenshot({ path: '/tmp/opencode/f-start.png' });

  // build workshop, return to cab, show badge
  await page.evaluate(() => {
    S.train.moving = false;
    S.train.carts.push({ type: 'workshop', store: 0, t: 0, cool: 0, aim: -Math.PI / 2 });
    S.player.ly = 120; S.player.lx = 0;
    S.train.fuel = 48; S.inv = { wood: 2, coal: 2, scrap: 4, food: 1 };
  });
  await page.waitForTimeout(400);
  await page.screenshot({ path: '/tmp/opencode/f-workshop-badge.png' });

  // stand in workshop
  await page.evaluate(() => { S.player.ly = 263; S.train.moving = false; });
  await page.waitForTimeout(350);
  await page.screenshot({ path: '/tmp/opencode/f-workshop-zone.png' });

  // open catalogue
  await page.evaluate(() => {
    S.player.ly = 263;
    S.train.carts.push({ type: 'green', store: 2, t: 9, cool: 0, aim: -Math.PI / 2 });
    S.train.carts.push({ type: 'turret', store: 0, t: 0, cool: 0, aim: -Math.PI / 2 });
    S.inv = { wood: 9, coal: 3, scrap: 7, food: 2 };
    openBuild();
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/opencode/f-catalogue.png' });
  await page.evaluate(() => closeBuild());

  // off train near moving train -> JUMP ON
  await page.evaluate(() => {
    S.train.moving = true; S.train.fuel = 60;
    S.player.aboard = false; S.player.lx = 0; S.player.x = 32; S.player.y = S.train.y + 200;
  });
  await page.waitForTimeout(300);
  await page.screenshot({ path: '/tmp/opencode/f-jumpon.png' });

  // full consist
  await page.goto(base + '?shot=deck&sim=30');
  await page.waitForTimeout(600);
  await page.screenshot({ path: '/tmp/opencode/f-consist.png' });

  console.log(errors.length ? errors.join('\n') : 'no page errors');
  await browser.close();
})();

