const { chromium } = require('playwright');
const path = require('path');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.goto('file://' + path.resolve('index.html'));
  await page.waitForTimeout(400);
  await page.click('#go');
  await page.waitForTimeout(200);

  const result = await page.evaluate(() => {
    S.mode = 'play';
    let err = null, built = 0, deaths = 0, boards = 0, offs = 0;
    for (let i = 0; i < 30000; i++) {
      // wander randomly, occasionally act
      S.joy.dx = Math.sin(i * 0.071) * (i % 7 < 3 ? 1 : .2);
      S.joy.dy = Math.cos(i * 0.053) * (i % 11 < 4 ? 1 : .2);
      if (i % 900 === 0) doAct();
      if (i % 1700 === 0 && S.player.aboard) doTrain();
      if (i % 2100 === 0 && S.player.aboard) doFuel();
      if (i % 2600 === 0 && S.player.aboard) doEat();
      try { update(1 / 60); } catch (e) { err = e.message + ' @ ' + (e.stack || '').split('\n')[1]; break; }
      if (S.mode === 'win' || S.mode === 'dead') {
        if (S.mode === 'win') { S.mode = 'play'; }
        else { deaths++; S.mode = 'play'; S.player.hp = 100; S.player.aboard = false; }
      }
      // keep the run going
      if (S.train.fuel < 35) S.train.fuel = 80;
      if (S.train.carts.length === 0 && S.player.aboard && i % 120 === 0) { S.inv.wood = 9; S.inv.scrap = 9; buildCart('workshop'); built++; }
      if (S.train.carts.length === 1 && inZone('workshop') && i % 300 === 0) {
        S.inv = { wood: 50, coal: 50, scrap: 50, food: 20 };
        for (const t of ['plow','bunker','green','turret','medic']) { buildCart(t); built++; }
      }
      if (i === 15000) S.train.y = -GOAL_M * PPM + 20000;
    }
    return { err, built, deaths, carts: S.train.carts.map(c => c.type), y: S.train.y, mode: S.mode, zombies: S.zombies.length, parts: S.parts.length, fuel: S.train.fuel };
  });
  console.log(result);
  console.log(errors.length ? errors.join('\n') : 'no page errors');
  await browser.close();
  if (result.err) process.exit(1);
})();

const { chromium } = require('playwright');
const path = require('path');
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, isMobile: true });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERR ' + e.message));
  await page.goto('file://' + path.resolve('index.html') + '?shot=deck&sim=10');
  await page.waitForTimeout(400);

  // cart functions on the deck consist
  const r = await page.evaluate(() => {
    const out = {};
    // max fuel with bunker
    out.fuelMax = fuelMax();
    // greenhouse harvest: stand in green zone
    const gs = segs().find(s => s.type === 'green');
    S.player.ly = (gs.y0 + gs.y1) / 2; S.player.lx = 0;
    const before = S.inv.food;
    gs.ref.store = 3; gs.ref.t = 0;
    update(1 / 60);
    out.green = { before, after: S.inv.food, store: gs.ref.store };
    // medic heals
    const ms = segs().find(s => s.type === 'medic');
    S.player.ly = (ms.y0 + ms.y1) / 2;
    S.player.hp = 50;
    for (let i = 0; i < 60; i++) update(1 / 60);
    out.medicHp = S.player.hp;
    // turret shoots zombies near its car
    const ts = segs().find(s => s.type === 'turret');
    const cy = S.train.y + (ts.y0 + ts.y1) / 2;
    S.zombies = [{ x: 60, y: cy, hx: 60, hy: cy, hp: 2, wob: 0, t: 0 }];
    S.player.ly = 120; // away from the turret but aboard
    for (let i = 0; i < 60; i++) update(1 / 60);
    out.turretZombies = S.zombies.length;
    out.beams = S.beams.length;
    // plow eats debris with no fuel loss
    S.train.moving = true; S.train.fuel = 80;
    S.train.y = -1000;
    const chunk = genChunk(-3);
    chunk.push({ type: 'debris', kind: 'log', x: 0, y: S.train.y - 40, hp: 2 });
    const scrap = S.inv.scrap;
    for (let i = 0; i < 30; i++) update(1 / 60);
    out.plow = { fuel: +S.train.fuel.toFixed(2), scrap: S.inv.scrap - scrap };
    return out;
  });
  console.log(r);
  assert(r.fuelMax === 140, 'bunker raises max fuel to 140');
  assert(r.green.after === r.green.before + 3 && r.green.store === 0, 'greenhouse harvests 3 food');
  assert(r.medicHp > 50, 'infirmary heals aboard');
  assert(r.turretZombies === 0, 'turret kills nearby infected');
  assert(r.plow.scrap >= 1, 'plow clears debris for scrap');
  assert(r.plow.fuel > 70, 'plow prevents debris fuel damage');

  console.log(errors.length ? errors.join('\n') : 'no page errors');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

