const { chromium } = require('playwright');
const path = require('path');
const assert = (c, m) => { if (!c) throw new Error('FAIL: ' + m); console.log('ok -', m); };
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true });
  await page.goto('file://' + path.resolve('index.html') + '?shot=off&sim=5');
  await page.waitForTimeout(300);
  const r = await page.evaluate(() => {
    S.train.moving = false;
    const baseY = -5000;
    // isolate a test chunk
    const list = genChunk(Math.floor(baseY / CHUNK));
    const out = {};
    S.player.aboard = false; S.player.x = 0; S.player.y = baseY;

    const tree = { type: 'tree', x: 0, y: baseY + 32, amt: 2, s: .5 };
    list.push(tree);
    S.player.y = baseY;
    const found = nearestRes();
    out.treeFound = !!(found && found.type === 'tree');
    const before = S.inv.wood;
    if (found) collect(found);
    out.treeWood = S.inv.wood - before;
    out.treeTaken = !!tree.taken;

    // decorative/obstacle types must never be auto-collected
    const props = [
      { type: 'grass', x: 0, y: baseY, amt: 1 },
      { type: 'rock', x: 0, y: baseY, amt: 1 },
      { type: 'debris', x: 0, y: baseY, kind: 'log', hp: 2, amt: 2 },
    ];
    out.decor = props.map(p => { list.push(p); return nearestRes(); });
    out.decorTypes = out.decor.map(p => p && p.type);
    out.decorTaken = props.map(p => !!p.taken);
    return out;
  });
  console.log(r);
  assert(r.treeFound, 'tree within chopping reach is detected');
  assert(r.treeWood === 3 && r.treeTaken, 'tree yields wood when reached');
  assert(r.decorTypes.every(t => t === undefined || t === null), 'grass, rocks and debris are not auto-picked up');
  assert(r.decorTaken.every(t => !t), 'decorative props are not marked taken');
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

